head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MENU_CD_SPAC = "05263";       // 기업인수목적회사 메뉴 코드 끝자리 (원본 pMenuID == "STF05263") — TODO: TO-BE 메뉴 코드 체계 확인 (§10 #6)
scwin.MKT_TP_KOSDAQ = "2";          // 회사 시장구분 — 코스닥이면 명세 ② 코스닥 목록 (§10 #2)
scwin.POPUP_PATH = "/ui/lst/lstproc/";      // 등록 팝업 배포 경로 (원본 ../lstproc/{ID}.gfm — 경로 가정, §10 #1)
scwin.isSpac = false;       // 기업인수목적회사 메뉴 여부 (원본 spacYN)
scwin.secugrpId = "";       // 증권그룹ID — 두 메뉴 모두 주권(ST), 회사 선택 결과로 바뀔 수 있다 (원본 fr_SecuGrpId)
scwin.mktTpCd = "";         // 고른 회사의 시장구분 1: 유가, 2: 코스닥, 6: 코넥스 (회사 찾기 결과 SPOT_ISU_TRD_MKT_TP_CD)
scwin.isKsqList = false;    // 지금 목록이 명세 ② 코스닥 목록인지
// 신규등록구분(관리종목지정업무구분코드) → 등록 팝업. 크기는 원본 CreateDialogFrame 값(기업인수목적회사 메뉴는 일부 높이가 다르다)
scwin.POPUPS = {
    "0" : { id : "ULDSTF05215", name : "관리종목지정", width : 620, height : 450, spacWidth : 615, spacHeight : 430 },
    "1" : { id : "ULDSTF05216", name : "관리종목지정 사유변경", width : 620, height : 520, spacWidth : 620, spacHeight : 520 },
    "2" : { id : "ULDSTF05217", name : "관리종목지정 사유 및 유의사항 변경", width : 620, height : 650, spacWidth : 615, spacHeight : 650 },
    "3" : { id : "ULDSTF05218", name : "유의사항 변경", width : 620, height : 520, spacWidth : 615, spacHeight : 450 },
    "4" : { id : "ULDSTF05219", name : "관리종목지정 해제", width : 615, height : 450, spacWidth : 615, spacHeight : 450 },
    "5" : { id : "ULDSTF05226", name : "상장폐지기준 적용 유예", width : 620, height : 450, spacWidth : 615, spacHeight : 450 },
    "6" : { id : "ULDSTF05227", name : "상장폐지기준 적용 유예기간 변경", width : 620, height : 450, spacWidth : 615, spacHeight : 450 }
};
// 그리드 열 — 시장별로 보이는 열 (명세 ① 유가 등 / 명세 ② 코스닥)
scwin.COLS_KSE = ["mktactEnforceDd", "admisuDesignBzTpNm", "bfchgDelistBasDdContn", "afchgDelistBasDdContn", "chgRsnContn"];
scwin.COLS_KOSDAQ = ["admisuDesnrelsDd", "admisuRsnChgDd", "rsnChgTpNm"];

// 원본 : /lstproc/ULDSTF05214.gfm (관리종목지정(유) — 메뉴 STF05214 주권, STF05263 기업인수목적회사가 같은 화면을 쓴다)
/*
 * 화면 동작
 *  - [회사 찾기]로 회사를 고르면 그 회사의 관리종목지정 내역을 조회한다. 그 뒤에는 [조회]로 다시 조회한다.
 *  - 회사 시장구분이 코스닥이면 명세 ② 코스닥 목록을 부르고, 그리드를 지정일·사유변경일·사유변동 열로 바꿔 보인다.
 *  - 하단 [신규등록구분]을 고르고 [신규]를 누르면 구분별 등록 팝업(ULDSTF05215~05219·05226·05227)을 연다.
 *    목록 행 더블클릭은 그 행의 구분 팝업을 수정으로 연다. 팝업이 저장을 알리거나 X 로 닫히면 다시 조회한다.
 *  - [엑셀다운로드]로 목록을 내려받는다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05214/ULDSTF05214.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05214.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 메뉴로 기업인수목적회사 여부·증권그룹을 정하고, 조회 영역 Enter 키를 바인딩하고, 목록을 유가 열로 둔다.
 * 회사를 고르기 전이라 조회는 하지 않는다(원본과 같음). (원본 전역 선언 + gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 메뉴 — 원본 pMenuID = InfoMenuID(), fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()) (두 메뉴 모두 ST)
    const menuInfo = $c.data.getParameter("menuInfo") ?? {};
    scwin.isSpac = String(menuInfo.menuCode ?? "").endsWith(scwin.MENU_CD_SPAC);
    scwin.secugrpId = $c.lc.glb.SECUGRP_ID_ST;

    // 2) 조회 영역 Enter 키(규칙 22) — 입력란은 읽기 전용이지만 영역 포커스에서 조회한다
    $c.win.setEnterKeyEvent(pan_Cnd, scwin.img_Search_onclick);

    // 3) 목록 열 — 회사를 고르기 전에는 유가 열 (§6.3)
    scwin.setListView(false);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_IsuCdSearch_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 회사 찾기(돋보기) 버튼 클릭 (원본 btn_IsuCdSearch onclick → fn_PopFindCorpChrgSW + fn_SetParIsur)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_IsuCdSearch_onclick = async function (e) {
    try {
        await scwin.openCompanyPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05214.btn_IsuCdSearch_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러) — 회사를 골랐는지 먼저 본다. (원본 img_Search onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_Search_onclick = async function (e) {
    try {
        if (!(await scwin.validateCompany())) return;
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05214.img_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록 행 더블클릭 — 그 행의 구분 팝업을 수정으로 연다. (원본 grd_List OnDblClick)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetail(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05214.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.img_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀다운로드 버튼 클릭 (원본 img_Excel onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_Excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05214.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_Regist_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 버튼 클릭 (원본 img_Regist onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_Regist_onclick = async function (e) {
    try {
        await scwin.writeNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05214.img_Regist_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 관리종목지정 목록 조회. (원본 fn_search — /administrativeIssue.do searchAdministrativeIssue DIV_IDX_ADMISU_LIST, 명세 ① — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/stock/administrative-issue/select-list",
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    // 명세 ① requestData { isurCd }
    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : dma_search.get("isurCd") });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError → alert_error)
};

/**
 * @method
 * @name scwin.selectKsqList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 코스닥 관리종목지정 목록 조회 — 고른 회사가 코스닥일 때. (원본에 없음 — 명세 ② select-ksq-list, §5.2·§10 #2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectKsqList = async function () {
    const sbmOptions = {
        id : "sbm_selectKsqList",
        method : "get",
        action : "/api/listing/lstproc/stock/administrative-issue/select-ksq-list",
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    // 명세 ② requestData { isurCd } — 응답 dlt_ksqList 열을 같은 그리드 목록에 받는다
    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : dma_search.get("isurCd") });
    if (result?.skipped) return false;
    return result.responseJSON?.success === true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 회사 시장구분에 따라 목록(유가 등 ① / 코스닥 ②)을 조회하고, 그리드 열을 맞추고 건수를 적는다. (원본 fn_search + dts_List OnLoadCompleted — §6.1)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    // 조회 전 목록·건수를 비운다 — 조회가 실패하면 앞 회사의 행으로 팝업을 여는 일이 없도록
    dlt_list.removeAll();
    txb_TotCnt.setValue("0");

    const isKsq = (scwin.mktTpCd === scwin.MKT_TP_KOSDAQ);
    scwin.setListView(isKsq);
    const ok = isKsq ? await scwin.selectKsqList() : await scwin.selectList();
    if (!ok) return;

    txb_TotCnt.setValue(dlt_list.getRowCount());      // 원본 FillGridHeaderTotalCnt(rowcount, panel_page)
};

/**
 * @method
 * @name scwin.validateCompany
 * @author Inswave
 * @date 2026. 10. 30
 * @description 회사를 골랐는지 본다. 안 골랐으면 MSG-0013 을 띄우고 회사 찾기 버튼에 포커스한다. (원본 img_Search·img_Regist onclick 공통 검사 — §6.1)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validateCompany = async function () {
    if ($c.util.isEmpty(dma_search.get("isurCd"))) {
        // MSG-0013 "[회사코드(명)]을 선택해주세요."
        await $c.win.alert($c.stf.getMessageParam("MSG-0013", ""));
        btn_IsuCdSearch.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.openCompanyPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 회사 찾기. 기업인수목적회사 메뉴면 SPAC 회사("1"), 아니면 주권 회사("2") 목록에서 고른다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 btn_IsuCdSearch onclick + fn_GetParIsur/fn_SetParIsur + fn_PopFindCorpChrgSW — §6.2·§6.5)
 * @returns
 * @hidden N
 */
scwin.openCompanyPopup = async function () {
    // 92009_SW 는 행을 더블클릭했을 때만 DBCLICKYN "Y" 와 회사를 돌려준다. 취소·닫기(X)는 { isCloseButtonClick } 객체다(선례 ULDSTF05232).
    const res = await $c.lc.popFindCorpChrgSW(scwin.secugrpId, scwin.isSpac ? "1" : "2");
    if (res?.DBCLICKYN !== "Y" || $c.util.isEmpty(res?.ISUR_CD)) return;

    await scwin.setCompany(res);
};

/**
 * @method
 * @name scwin.setCompany
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 회사를 조회조건에 넣고 바로 조회한다. (원본 fn_SetParIsur — §6.2)
 * @param {Object} res 회사 선택 결과 { ISUR_CD, COM_NM, SPOT_ISU_TRD_MKT_TP_CD, SECUGRP_ID }
 * @returns
 * @hidden N
 */
scwin.setCompany = async function (res) {
    dma_search.set("isurCd", String(res.ISUR_CD ?? ""));
    dma_search.set("comNm", String(res.COM_NM ?? ""));
    scwin.secugrpId = String(res.SECUGRP_ID ?? "") || scwin.secugrpId;
    scwin.mktTpCd = String(res.SPOT_ISU_TRD_MKT_TP_CD ?? "");

    await scwin.search();
};

/**
 * @method
 * @name scwin.setListView
 * @author Inswave
 * @date 2026. 10. 30
 * @description 그리드 열을 시장에 맞춘다 — 유가 등은 시행일·구분·유의사항·변경/해제 사유, 코스닥은 지정일·사유변경일·사유변동. (명세 ①·② 응답 열 차이 — §6.3)
 * @param {Boolean} isKsq 코스닥 목록이면 true
 * @returns
 * @hidden N
 */
scwin.setListView = function (isKsq) {
    scwin.isKsqList = isKsq;
    scwin.COLS_KSE.forEach(colId => grd_List.setColumnVisible(colId, !isKsq));
    scwin.COLS_KOSDAQ.forEach(colId => grd_List.setColumnVisible(colId, isKsq));
};

/**
 * @method
 * @name scwin.getPopupData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록 팝업에 넘길 data. 신규는 업무처리번호·종목이 빈 값이고 구분은 신규등록구분, 수정은 더블클릭한 행 값이다.
 * (원본 fn_GetParNew / fn_GetParUpdate 의 arrPar[0..8] — §6.4·§6.5)
 * @param {Number} rowIndex 수정할 행(화면 번호). 신규면 -1
 * @param {String} bzTpCd 관리종목지정업무구분코드 0~6
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getPopupData = function (rowIndex, bzTpCd) {
    const isNew = (rowIndex < 0);
    return {
        isurCd : dma_search.get("isurCd"),                  // arr[0] 발행기관코드
        isurNm : dma_search.get("comNm"),                   // arr[1] 발행기관명
        secugrpId : scwin.secugrpId,                        // arr[2] 증권그룹
        mktId : $c.session.getUserInfo("market"),           // arr[3] 시장구분 (원본 fn_getMktId() — 로그인 사용자 시장)
        bzProcsNo : isNew ? "" : dlt_list.getCellData(rowIndex, "bzProcsNo"),   // arr[4] 업무처리번호 (신규는 없음)
        admisuDesignBzTpCd : bzTpCd,                        // arr[5] 관리종목지정업무구분코드
        spacYn : scwin.isSpac ? "Y" : "N",                  // arr[6] 기업인수목적회사 구분
        isuCd : isNew ? "" : dlt_list.getCellData(rowIndex, "isuCd"),           // arr[7] 종목코드 (수정만)
        isuNm : isNew ? "" : dlt_list.getCellData(rowIndex, "isuNm")            // arr[8] 종목명 (수정만)
    };
};

/**
 * @method
 * @name scwin.openRegPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 구분 코드의 등록 팝업을 data 로 열고 닫힐 때까지 기다린다. 저장했다고 돌려주거나 X 로 닫히면 목록을 다시 조회한다.
 * 연 뒤에는 신규등록구분을 "선택해주세요"로 되돌린다. 모르는 구분이면 원본처럼 아무것도 하지 않는다. (원본 fn_newpre_create_frame — §6.4·§6.5)
 * @param {String} bzTpCd 관리종목지정업무구분코드 0~6
 * @param {Object} data 넘길 data (scwin.getPopupData)
 * @returns
 * @hidden N
 */
scwin.openRegPopup = async function (bzTpCd, data) {
    const pop = scwin.POPUPS[String(bzTpCd ?? "")];
    if (!pop) return;

    const options = {
        id : pop.id,
        // 원본 제목 — 주권 메뉴는 "주권 {구분}", 기업인수목적회사 메뉴는 "기업인수목적회사 {구분}"
        popupName : (scwin.isSpac ? "기업인수목적회사" : $c.lc.getSecuGrpNm(scwin.secugrpId)) + " " + pop.name,
        width : scwin.isSpac ? pop.spacWidth : pop.width,
        height : scwin.isSpac ? pop.spacHeight : pop.height,
        type : "pageFramePopup"
    };

    // TODO: ULDSTF05215~05219·05226·05227 은 미전환 — 경로·data 키·반환 { isSaved } 는 제안이다 (§10 #1)
    const result = await $c.win.openPopup(scwin.POPUP_PATH + pop.id + ".xml", options, data);
    cmb_RegistTyp.setValue("");      // 원본 cmb_RegistTyp.index = 0

    // 원본은 팝업이 닫혀도 다시 조회하지 않았다(fn_search 주석) — 저장 결과를 보이도록 다시 조회한다(§8 #3)
    if (result?.isSaved === true || result?.isCloseButtonClick === true) {
        await scwin.search();
    }
};

/**
 * @method
 * @name scwin.writeNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 — 회사와 신규등록구분을 골랐는지 보고, 그 구분의 등록 팝업을 신규로 연다. (원본 img_Regist onclick — §6.4)
 * @returns
 * @hidden N
 */
scwin.writeNew = async function () {
    if (!(await scwin.validateCompany())) return;

    const bzTpCd = cmb_RegistTyp.getValue();
    if ($c.util.isEmpty(bzTpCd)) {
        // MSG-0014 "[신규등록구분]을 선택해주세요."
        await $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
        cmb_RegistTyp.focus();
        return;
    }
    await scwin.openRegPopup(bzTpCd, scwin.getPopupData(-1, bzTpCd));
};

/**
 * @method
 * @name scwin.openDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 — 그 행의 관리종목지정업무구분코드로 팝업을 연다. 코스닥 목록은 구분코드 열이 없어 사유변동구분으로 대신한다. (원본 grd_List OnDblClick — §6.4, §10 #3)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.openDetail = async function (rowIndex) {
    if (rowIndex < 0) return;
    // TODO: 명세 ② 코스닥 목록에는 admisuDesignBzTpCd 가 없다 — rsnChgTpCd 가 같은 코드(0~6)인지 확인 (§10 #3)
    const bzTpCd = dlt_list.getCellData(rowIndex, "admisuDesignBzTpCd") || dlt_list.getCellData(rowIndex, "rsnChgTpCd");
    await scwin.openRegPopup(bzTpCd, scwin.getPopupData(rowIndex, bzTpCd));
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 GridToExcel(증권그룹명 + "괸리종목지정내역", "", "8"), doLogSave 삭제 — §6.6)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    await $c.data.downloadGridViewExcel(grd_List, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42) — 원본 오타 「괸리」 정정
        fileName : $c.win.getProgramId() + "_" + $c.lc.getSecuGrpNm(scwin.secugrpId) + "관리종목지정내역_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};
